describe('Dynamic Loading - Reveal Hidden Content After Asynchronous Wait', () => {
  beforeEach(() => {
    cy.visit('/dynamic_loading/1');
  });

  it('should reveal hidden content after asynchronous load with loading indicator', () => {
    // Verify initial state: loading indicator is hidden
    cy.get('[data-testid="loading-indicator"]').should('not.exist');
    cy.get('[data-testid="finish-button"]').should('be.visible');

    // Click Start button to initiate loading
    cy.get('[data-testid="start-button"]').click();

    // Verify loading indicator appears
    cy.get('[data-testid="loading-indicator"]').should('be.visible');

    // Wait for the asynchronous operation to complete
    cy.intercept('GET', '/api/load-content').as('loadContent');
    cy.wait('@loadContent');

    // Verify loading indicator disappears
    cy.get('[data-testid="loading-indicator"]').should('not.exist');

    // Verify 'finish' element becomes visible with content
    cy.get('[data-testid="finish-button"]').should('be.visible');
    cy.get('[data-testid="finish-content"]').should('contain', 'Hello World!');

    // Verify loading state is no longer active
    cy.get('[data-testid="loading-indicator"]').should('not.exist');
  });

  it('should handle failed asynchronous load and display error message', () => {
    // Intercept the API call with a 500 error
    cy.intercept('GET', '/api/load-content', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('loadContentError');

    // Click Start button to initiate loading
    cy.get('[data-testid="start-button"]').click();

    // Verify loading indicator appears
    cy.get('[data-testid="loading-indicator"]').should('be.visible');

    // Wait for the failed API call
    cy.wait('@loadContentError');

    // Verify loading indicator disappears
    cy.get('[data-testid="loading-indicator"]').should('not.exist');

    // Verify error message is displayed instead of content
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load content');

    // Verify 'finish' button is still visible but disabled
    cy.get('[data-testid="finish-button"]').should('be.visible');
    cy.get('[data-testid="finish-button"]').should('be.disabled');
  });
});
